import { test, expect } from '@playwright/test';

test.describe('Dark Mode Toggle Preferences', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/settings');
  });

  test('should successfully toggle dark mode from preferences and apply to the app', async ({ page }) => {
    // Verify dark mode is disabled by default
    const darkModeToggle = page.getByRole('button', { name: /dark mode/i });
    await expect(darkModeToggle).toBeVisible();
    await expect(darkModeToggle).toHaveAttribute('aria-pressed', 'false');

    // Verify the app is in light mode
    const appBackground = page.getByTestId('app-background');
    await expect(appBackground).toHaveStyle('background-color: #ffffff');

    // Verify the toggle button is disabled when dark mode is disabled
    await expect(darkModeToggle).toHaveAttribute('disabled', 'true');

    // Click the dark mode toggle button to enable dark mode
    await darkModeToggle.click();

    // Verify the toggle button is now enabled
    await expect(darkModeToggle).not.toHaveAttribute('disabled', 'true');

    // Verify the toggle button is now active
    await expect(darkModeToggle).toHaveAttribute('aria-pressed', 'true');

    // Verify the app background color changes to dark mode
    await expect(appBackground).toHaveStyle('background-color: #000000');

    // Verify the toggle button text changes to reflect the active state
    const toggleText = page.getByText(/dark mode/i);
    await expect(toggleText).toContainText('enabled');

    // Verify the toggle button is visible and accessible
    await expect(darkModeToggle).toBeVisible();

    // Verify the toggle button is still accessible using getByRole
    const toggleButton = page.getByRole('button', { name: /dark mode/i });
    await expect(toggleButton).toBeVisible();
  });

  test('should revert to light mode when dark mode is disabled from preferences', async ({ page }) => {
    // Verify dark mode is enabled by default
    const darkModeToggle = page.getByRole('button', { name: /dark mode/i });
    await expect(darkModeToggle).toBeVisible();
    await expect(darkModeToggle).toHaveAttribute('aria-pressed', 'true');

    // Verify the app is in dark mode
    const appBackground = page.getByTestId('app-background');
    await expect(appBackground).toHaveStyle('background-color: #000000');

    // Verify the toggle button is enabled
    await expect(darkModeToggle).not.toHaveAttribute('disabled', 'true');

    // Click the dark mode toggle button to disable dark mode
    await darkModeToggle.click();

    // Verify the toggle button is now disabled
    await expect(darkModeToggle).toHaveAttribute('disabled', 'true');

    // Verify the toggle button is now inactive
    await expect(darkModeToggle).not.toHaveAttribute('aria-pressed', 'true');

    // Verify the app background color reverts to light mode
    await expect(appBackground).toHaveStyle('background-color: #ffffff');

    // Verify the toggle button text reverts to reflect the disabled state
    const toggleText = page.getByText(/dark mode/i);
    await expect(toggleText).toContainText('disabled');

    // Verify the toggle button is still visible and accessible
    await expect(darkModeToggle).toBeVisible();
  });
});
